(function(){
'use strict';
const c=window.ConferenceCore,esc=window.HubCore.escapeHTML;
let records=[],ready=false,mountId=0;
function label(iso){return c.dateLabel(iso);}
function message(node,text,success=false){node.textContent=text;node.className=success?'success-text form-status':'error-text form-status';}
async function request(action,body){const response=await fetch('/api/hub'+(action?'?action='+action:''),body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{cache:'no-store'});const data=await response.json().catch(()=>({error:'The service is unavailable. Please try again.'}));if(!response.ok)throw Error(data.error||'Please try again.');return data;}
function management(){try{return JSON.parse(localStorage.getItem('pccm-presentations')||'{}');}catch{return {};}}
function saveManagement(date,token){try{const values=management();if(token)values[date]=token;else delete values[date];localStorage.setItem('pccm-presentations',JSON.stringify(values));}catch{}}
function row(date){const r=records.find(r=>r.date===date);return `<article class="schedule-row"><div class="schedule-date">${esc(new Date(date+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'}))}<small>Wednesday · noon CT</small></div><div><h3 class="schedule-topic">${r?esc(r.topic):'Presenter slot'}</h3><div class="schedule-meta ${r?'':'slot-open'}">${r?esc(r.name)+' · '+esc(r.kind):ready?'Open for sign-up':'Sign-up not available yet'}</div></div><div class="schedule-actions">${r?(management()[date]?`<button class="text-button" data-cancel="${date}">Cancel my slot</button>`:''):(ready?`<button class="button" data-book="${date}">Sign up to present</button>`:'')}<button class="text-button" data-calendar="${date}">Add to calendar</button></div></article>`;}
function draw(){const target=document.getElementById('research-schedule');if(!target)return;let month='';target.innerHTML=c.dates().map(date=>{const key=date.slice(0,7);let heading='';if(key!==month){month=key;heading=`<h2 class="schedule-month">${esc(new Date(date+'T12:00:00Z').toLocaleDateString('en-US',{month:'long',year:'numeric',timeZone:'UTC'}))}</h2>`;}return heading+row(date);}).join('');target.querySelectorAll('[data-book]').forEach(button=>button.addEventListener('click',()=>showForm(button.dataset.book)));target.querySelectorAll('[data-calendar]').forEach(button=>button.addEventListener('click',()=>calendar(button.dataset.calendar)));target.querySelectorAll('[data-cancel]').forEach(button=>button.addEventListener('click',()=>cancel(button.dataset.cancel)));}
function calendar(date){const timestamp=c.startTime(date).toISOString().replace(/[-:]/g,'').replace('.000','');const r=records.find(r=>r.date===date);const text=(r?'PCCM Research: '+r.topic:'PCCM research conference').replace(/[\\,;\n]/g,char=>'\\'+char);const file=new Blob(['BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//CTS Research Hub//Research Conference//EN\r\nBEGIN:VEVENT\r\nUID:pccm-'+date+'@ctsresearchhub.org\r\nDTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace('.000','')+'\r\nDTSTART:'+timestamp+'\r\nSUMMARY:'+text+'\r\nDESCRIPTION:Second and fourth Wednesdays at noon Central. Confirm location with the section.\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n'],{type:'text/calendar'});const link=document.createElement('a');link.href=URL.createObjectURL(file);link.download='PCCM-research-'+date+'.ics';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);}
function showForm(date){const panel=document.getElementById('booking-panel');panel.innerHTML=`<form id="presenter-form" class="booking-form"><h2>Present on ${esc(label(date))}</h2><p>Noon Central · PCCM research conference</p><div class="form-pair"><label>Your name<input name="name" autocomplete="name" required maxlength="100"></label><label>LSU Health email<input name="email" type="email" autocomplete="email" placeholder="you@lsuhsc.edu" required maxlength="254" pattern="[^@\\s]+@lsuhsc\\.edu"></label></div><label>Presentation topic<input name="topic" required maxlength="200" placeholder="A short working title is fine"></label><label>Type of presentation<select name="kind"><option>Work in progress</option><option>New project or proposal</option><option>Research results</option><option>Manuscript discussion</option></select></label><div class="form-trap" aria-hidden="true"><input name="website" tabindex="-1" autocomplete="off" aria-label="Leave blank"></div><p class="quiet-note">Your name and topic will appear on this public schedule; your email will remain private. Please use your own @lsuhsc.edu address. Do not include patient information.</p><label class="check-label"><input type="checkbox" name="consent" required>I agree to display my name and presentation topic.</label><button class="button" type="submit">Reserve this date</button> <button class="text-button" type="button" id="close-booking">Close</button><p id="booking-status" role="status" tabindex="-1"></p></form>`;panel.scrollIntoView({behavior:'smooth',block:'start'});panel.querySelector('input[name="name"]').focus({preventScroll:true});document.getElementById('close-booking').onclick=()=>panel.innerHTML='';document.getElementById('presenter-form').onsubmit=async event=>{event.preventDefault();const form=event.target,status=document.getElementById('booking-status'),button=form.querySelector('button[type="submit"]'),values=Object.fromEntries(new FormData(form));if(!c.isEmail(values.email)){message(status,'Please use your @lsuhsc.edu email address.');return;}button.disabled=true;message(status,'Saving your presentation…',true);try{const result=await request('book',{...values,date});saveManagement(date,result.manageToken);records=result.bookings;draw();const manageLink=location.origin+'/#conferences?date='+date+'&manage='+encodeURIComponent(result.manageToken);status.className='success-text form-status';status.innerHTML=`Your presentation is reserved for ${esc(label(date))}. <a href="${esc(manageLink)}">Save this private link to cancel your booking</a>.`;form.reset();button.hidden=true;status.focus();}catch(error){message(status,error.message);button.disabled=false;}};}
async function cancel(date,token){const panel=document.getElementById('booking-panel');panel.innerHTML=`<div class="booking-form"><h2>Cancel your presentation?</h2><p>${esc(label(date))} · noon Central</p><button class="button" id="confirm-cancel">Cancel my presentation</button><p id="cancel-status" role="status"></p></div>`;panel.scrollIntoView({behavior:'smooth'});document.getElementById('confirm-cancel').onclick=async event=>{event.target.disabled=true;try{const result=await request('cancel',{date,manageToken:token||management()[date]});records=result.bookings;saveManagement(date,null);draw();message(document.getElementById('cancel-status'),'Your presentation has been canceled. The date is available again.',true);}catch(error){message(document.getElementById('cancel-status'),error.message);event.target.disabled=false;}};}
async function mount(params){const id=++mountId;ready=false;records=[];draw();try{const result=await request('schedule');if(id!==mountId||!document.getElementById('research-schedule'))return;ready=result.bookingEnabled;records=result.bookings||[];draw();if(params.get('manage')&&params.get('date'))cancel(params.get('date'),params.get('manage'));else if(params.get('date')&&c.dates().includes(params.get('date')))showForm(params.get('date'));}catch{if(id===mountId&&document.getElementById('research-schedule')){draw();document.getElementById('research-schedule').insertAdjacentHTML('afterbegin','<p class="quiet-note">The recurring dates are below. Online sign-up is being connected; reservations are not open yet.</p>');}}}
function bindGrant(){const form=document.getElementById('microgrant-form'),initialButton=document.getElementById('grant-submit'),initialStatus=document.getElementById('grant-status');initialButton.disabled=true;initialStatus.textContent='Checking application availability…';request('status').then(state=>{initialButton.disabled=!state.grantsEnabled;initialStatus.textContent=state.grantsEnabled?'':'Online applications will open once submission processing is connected.';initialStatus.className='quiet-note form-status';}).catch(()=>{initialStatus.textContent='Online applications will open once submission processing is connected.';initialStatus.className='quiet-note form-status';});form.onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(form)),status=document.getElementById('grant-status'),button=document.getElementById('grant-submit');if(!c.isEmail(values.email)){message(status,'Please use your @lsuhsc.edu email address.');return;}button.disabled=true;message(status,'Submitting your application…',true);try{const result=await request('microgrant',values);message(status,'Application received. Reference: '+result.reference+'. '+(result.notified?'It has been sent for review.':'Your application is saved; the review notification is pending.'),true);form.reset();status.focus();}catch(error){message(status,error.message);status.focus();}finally{button.disabled=false;}};}
window.HubSchedule={mount,bindGrant};
})();
